"use client";
import Image from "next/image";

import { Suspense, useCallback, useEffect, useRef, useState } from "react";
import { useSearchParams } from "next/navigation";
import { useDialog } from "@/lib/useDialog";
import { Eye, ShoppingBag, X } from "lucide-react";
import PageHeader from "@/components/ui/PageHeader";
import { Card, CardBody, CardHeader } from "@/components/ui/Card";
import Button from "@/components/ui/Button";
import EmptyState from "@/components/ui/EmptyState";
import ErrorBanner from "@/components/ui/ErrorBanner";
import Pagination from "@/components/ui/Pagination";
import Spinner from "@/components/ui/Spinner";
import { TableShell, Td, Thead } from "@/components/ui/Table";
import InfoGrid from "@/components/admin/InfoGrid";
import StatusBadge from "@/components/admin/StatusBadge";
import { fetchAdminOrderDetail, fetchAdminOrders } from "@/lib/admin/api";
import { STORE_ORDER_STATUS } from "@/lib/admin/status";
import type { AdminOrderDetail, AdminOrderListItem } from "@/lib/admin/types";
import type { Pagination as PaginationType } from "@/lib/api";
import { classifyStatus } from "@/lib/apiFailure";
import { formatCurrency, formatDate, formatDateTime, formatNumber } from "@/lib/format";
import { t } from "@/lib/strings";

const COLUMNS = [
  t.admin.orders.colOrderNumber,
  t.admin.orders.colStore,
  t.admin.orders.colCustomer,
  t.admin.orders.colItems,
  t.admin.orders.colDate,
  t.admin.orders.colTotal,
  t.admin.orders.colStatus,
  t.admin.orders.colAction,
] as const;

function AdminOrdersPageContent() {
  const searchParams = useSearchParams();
  const requestedOrder = Number(searchParams.get("orderId"));
  const detailRequest = useRef(0);
  const [orders, setOrders] = useState<AdminOrderListItem[]>([]);
  const [pagination, setPagination] = useState<PaginationType | null>(null);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [attempt, setAttempt] = useState(0);
  const [detail, setDetail] = useState<AdminOrderDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const res = await fetchAdminOrders({ page, limit: 20 });
      if (cancelled) return;
      setLoading(false);
      if (res.success && res.orders) {
        setOrders(res.orders);
        setPagination(res.pagination ?? null);
        setError("");
        return;
      }
      const failure = classifyStatus(res);
      setError(failure.kind === "unauthorized" ? t.admin.common.sessionInvalid : failure.message);
    })();
    return () => { cancelled = true; };
  }, [page, attempt]);

  const openDetail = useCallback(async (orderId: number) => {
    const request = ++detailRequest.current;
    setDetailLoading(true);
    setDetail(null);
    const res = await fetchAdminOrderDetail(orderId);
    if (request !== detailRequest.current) return;
    setDetailLoading(false);
    if (res.success && res.order) {
      setDetail(res.order);
      return;
    }
    const failure = classifyStatus(res);
    setError(failure.kind === "unauthorized" ? t.admin.common.sessionInvalid : failure.message);
  }, []);
  const closeDetail = useCallback(() => { detailRequest.current++; setDetail(null); setDetailLoading(false); }, []);
  const dialogRef = useDialog(detailLoading || !!detail, closeDetail);
  useEffect(() => {
    if (Number.isSafeInteger(requestedOrder) && requestedOrder > 0) {
      // Open the resource selected by an external notification URL.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      void openDetail(requestedOrder);
    }
    return () => { detailRequest.current++; };
  }, [requestedOrder, openDetail]);

  const total = pagination?.total ?? orders.length;
  const delivery = detail?.delivery;
  const deliveryAddress = [delivery?.city, delivery?.area, delivery?.street, delivery?.details]
    .filter(Boolean)
    .join(" — ");
  const productsTotal = detail?.money?.productsTotal ?? detail?.total ?? "0";
  const deliveryFee = detail?.money?.deliveryFee ?? delivery?.fee;
  return (
    <div className="flex flex-col gap-6">
      <PageHeader title={t.admin.orders.title} subtitle={total ? `${formatNumber(total)} ${t.admin.orders.count}` : t.admin.orders.globalSubtitle} />
      <ErrorBanner message={error} onRetry={() => { setLoading(true); setAttempt((value) => value + 1); }} />

      {loading ? <Spinner /> : orders.length === 0 ? (
        <Card><CardBody className="p-8"><EmptyState icon={ShoppingBag} title={t.admin.orders.empty} hint={t.admin.orders.globalSubtitle} /></CardBody></Card>
      ) : (
        <div className="flex flex-col gap-4">
          <Card className="overflow-hidden border border-border shadow-xs">
            <TableShell minWidth="min-w-[900px]"><Thead columns={COLUMNS} /><tbody className="divide-y divide-border/60">
              {orders.map((order) => <tr key={order.id} className="bg-surface transition hover:bg-primary-soft/40">
                <Td className="font-extrabold text-heading">{order.orderNumber}</Td>
                <Td>{order.store?.name ?? t.admin.common.none}</Td>
                <Td><p className="font-semibold text-heading">{order.customer?.name ?? order.recipientName}</p><p className="mt-1 text-xs text-text-secondary">{order.city ?? t.admin.common.none}</p></Td>
                <Td className="ltr-nums">{formatNumber(order.itemsCount)}</Td>
                <Td className="ltr-nums whitespace-nowrap text-text-secondary">{formatDate(order.createdAt)}</Td>
                <Td className="ltr-nums font-bold">{formatCurrency(Number(order.total))}</Td>
                <Td><StatusBadge meta={STORE_ORDER_STATUS[order.status]} /></Td>
                <Td><Button size="sm" variant="secondary" onClick={() => openDetail(order.id)} icon={<Eye className="size-3.5" aria-hidden="true" />}>{t.admin.orders.reviewOrder}</Button></Td>
              </tr>)}
            </tbody></TableShell>
          </Card>
          {pagination && <Pagination pagination={pagination} onChange={next => { if (next !== page) { setLoading(true); setPage(next); } }} />}
        </div>
      )}

      {(detailLoading || detail) && <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
        <button type="button" className="fixed inset-0 bg-black/40 backdrop-blur-xs" aria-label={t.common.close} onClick={closeDetail} />
        <div ref={dialogRef} role="dialog" aria-modal="true" aria-label={t.admin.orders.detailsTitle} tabIndex={-1} className="relative z-10 max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-3xl border border-border bg-app-bg shadow-2xl">
          <div className="sticky top-0 z-10 flex items-start justify-between border-b border-border bg-surface px-6 py-5 sm:px-8">
            <div><h2 className="text-xl font-black text-heading">{t.admin.orders.detailsTitle}</h2>{detail && <p className="mt-1 ltr-nums text-sm font-semibold text-text-secondary">{detail.orderNumber}</p>}</div>
            <Button variant="ghost" size="sm" onClick={closeDetail} icon={<X className="size-4" aria-hidden="true" />}>{t.common.close}</Button>
          </div>
          {detailLoading ? <div className="p-12"><Spinner /></div> : detail && <div className="space-y-5 p-5 sm:p-8">
            <section className="flex flex-col gap-4 rounded-2xl bg-primary p-5 text-icon sm:flex-row sm:items-center sm:justify-between">
              <div><p className="text-xs font-bold text-icon/70">حالة الطلب</p><div className="mt-2"><StatusBadge meta={STORE_ORDER_STATUS[detail.status]} /></div></div>
              <div className="grid grid-cols-2 gap-5 text-start sm:text-end"><div><p className="text-xs font-bold text-icon/70">إجمالي المنتجات</p><p className="mt-1 ltr-nums text-lg font-black">{formatCurrency(Number(productsTotal))}</p></div><div><p className="text-xs font-bold text-icon/70">الإجمالي المطلوب</p><p className="mt-1 ltr-nums text-lg font-black">{formatCurrency(Number(detail.total))}</p></div></div>
            </section>

            <div className="grid gap-5 md:grid-cols-2">
              <Card className="border border-border shadow-xs"><CardHeader title={t.admin.orders.customerInfo} /><CardBody><InfoGrid rows={[
                { label: t.admin.orders.colCustomer, value: detail.customer.name },
                { label: t.admin.users.email, value: <span dir="ltr">{detail.customer.email}</span> },
                { label: t.admin.users.phone, value: <span dir="ltr">{delivery?.recipientPhone ?? detail.customer.phone ?? t.admin.common.none}</span> },
                { label: t.admin.common.createdAt, value: <span className="ltr-nums">{formatDateTime(detail.createdAt)}</span> },
              ]} /></CardBody></Card>
              <Card className="border border-border shadow-xs"><CardHeader title={t.admin.orders.shippingAddress} /><CardBody><InfoGrid rows={[
                { label: t.admin.orders.colStore, value: detail.store.name },
                { label: "العنوان", value: deliveryAddress || t.admin.common.none },
                { label: "اسم المستلم", value: delivery?.recipientName ?? detail.customer.name },
                { label: "رسوم التوصيل", value: deliveryFee === null || deliveryFee === undefined ? t.admin.orders.freeShipping : <span className="ltr-nums">{formatCurrency(Number(deliveryFee))}</span> },
              ]} /></CardBody></Card>
            </div>

            <Card className="overflow-hidden border border-border shadow-xs"><CardHeader title={t.admin.orders.itemsList} /><CardBody className="p-0"><div className="divide-y divide-border/70">{detail.items.map((item) => {
              const unitPrice = item.unitPrice ?? item.price;
              const lineTotal = item.lineTotal ?? String(item.quantity * Number(unitPrice));
              const variant = [item.colorName ?? item.variant, item.sizeName ?? item.size].filter(Boolean).join(" · ");
              const image = item.image ?? item.productImage;
              return <article key={item.id} className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex min-w-0 items-center gap-4">{image ? <Image width={64} height={64} unoptimized src={image} alt="" className="size-16 shrink-0 rounded-xl border border-border object-cover" /> : <span className="grid size-16 shrink-0 place-items-center rounded-xl bg-field-bg text-xs font-bold text-text-secondary">منتج</span>}<div className="min-w-0"><p className="truncate text-base font-extrabold text-heading">{item.productName}</p>{variant && <p className="mt-1 text-sm text-text-secondary">{variant}</p>}</div></div>
                <div className="grid grid-cols-3 gap-3 rounded-xl bg-field-bg p-3 text-center sm:min-w-[290px]"><div><p className="text-[11px] font-bold text-text-secondary">عدد القطع</p><p className="mt-1 ltr-nums font-black text-heading">{item.quantity}</p></div><div><p className="text-[11px] font-bold text-text-secondary">سعر القطعة</p><p className="mt-1 ltr-nums font-black text-heading">{formatCurrency(Number(unitPrice))}</p></div><div><p className="text-[11px] font-bold text-text-secondary">إجمالي المنتج</p><p className="mt-1 ltr-nums font-black text-primary">{formatCurrency(Number(lineTotal))}</p></div></div>
              </article>;
            })}</div></CardBody></Card>
          </div>}
        </div>
      </div>}
    </div>
  );
}

export default function AdminOrdersPage() {
  return <Suspense fallback={<Spinner />}><AdminOrdersPageContent /></Suspense>;
}

"use client";
import Image from "next/image";

import { useCallback, useEffect, useRef, useState } from "react";
import { ArrowUpDown, Eye, Layers, MapPin, Package, Search, ShoppingBag, Store, User, XCircle } from "lucide-react";
import { Card } from "@/components/ui/Card";
import Badge from "@/components/ui/Badge";
import Button from "@/components/ui/Button";
import EmptyState from "@/components/ui/EmptyState";
import ErrorBanner from "@/components/ui/ErrorBanner";
import Pagination from "@/components/ui/Pagination";
import Spinner from "@/components/ui/Spinner";
import StatusBadge from "@/components/admin/StatusBadge";
import { TableShell, Td, Thead } from "@/components/ui/Table";
import { fetchStoreOrders, fetchAdminOrderDetail } from "@/lib/admin/api";
import { STORE_ORDER_STATUS } from "@/lib/admin/status";
import type {
  AdminOrderDetail,
  StoreOrder,
  StoreOrderItem,
  StoreOrderStatus,
} from "@/lib/admin/types";
import { formatCurrency, formatDate } from "@/lib/format";
import { t } from "@/lib/strings";
import type { Pagination as PaginationType } from "@/lib/api";

const ORDER_COLUMNS = [
  t.admin.orders.colOrderNumber,
  t.admin.orders.colCustomer,
  t.admin.orders.colItems,
  t.admin.orders.colAddress,
  t.admin.orders.colDate,
  t.admin.orders.colTotal,
  t.admin.orders.colPayment,
  t.admin.orders.colStatus,
  t.admin.orders.colAction,
] as const;

interface TabConfig {
  key: string;
  label: string;
  status: StoreOrderStatus | "";
}

const TABS: TabConfig[] = [
  { key: "all", label: t.admin.orders.tabAll, status: "" },
  { key: "PENDING", label: "بانتظار الموافقة", status: "PENDING" },
  { key: "ACCEPTED", label: "قيد التجهيز", status: "ACCEPTED" },
  { key: "DELIVERED", label: "تم التوصيل", status: "DELIVERED" },
  { key: "CANCELLED", label: "ملغي", status: "CANCELLED" },
  { key: "REJECTED", label: "مرفوض", status: "REJECTED" },
];

interface WireItem extends StoreOrderItem {
  product?: {name?: string; imageUrl?: string; image?: string};
  color?: string; size?: string | null;
}
interface WireOrder extends Omit<Partial<StoreOrder>, "items" | "address"> {
  id: number; code?: string; user?: {name?: string; phone?: string; email?: string};
  customer?: {name?: string; phone?: string; email?: string};
  phone?: string; email?: string; items?: WireItem[]; orderItems?: WireItem[];
  address?: string | {street?: string; city?: string};
  totalPrice?: string; amount?: string; paymentType?: string;
}

export default function StoreOrdersSection({ storeId }: { storeId: number }) {
  const requestId = useRef(0);
  const [orders, setOrders] = useState<StoreOrder[]>([]);
  const [counts, setCounts] = useState<Record<string, number>>({});
  const [pagination, setPagination] = useState<PaginationType | null>(null);
  const [activeTab, setActiveTab] = useState<string>("all");
  const [queryText, setQueryText] = useState("");
  const [sortOption, setSortOption] = useState<"newest" | "oldest" | "highest">("newest");
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedOrder, setSelectedOrder] = useState<StoreOrder | null>(null);
  const [orderDetail, setOrderDetail] = useState<AdminOrderDetail | null>(null);
  const [loadingDetail, setLoadingDetail] = useState(false);

  const handleOpenOrder = async (order: StoreOrder) => {
    setSelectedOrder(order);
    setLoadingDetail(true);
    setOrderDetail(null);
    try {
      const res = await fetchAdminOrderDetail(order.id);
      if (res.success && res.order) {
        setOrderDetail(res.order);
      }
    } catch {
      // fallback to selectedOrder
    } finally {
      setLoadingDetail(false);
    }
  };

  const loadOrders = useCallback(async () => {
    const currentRequest = ++requestId.current;
    setLoading(true);
    setError("");

    const currentTabObj = TABS.find((tab) => tab.key === activeTab);
    const status = currentTabObj?.status || "";

    const res = await fetchStoreOrders(storeId, {
      page,
      limit: 10,
      q: queryText,
      status,
      sort: sortOption,
    });

    if (currentRequest !== requestId.current) return;
    setLoading(false);

    if (res.success && Array.isArray(res.orders)) {
      const rawList: WireOrder[] = res.orders;

      const normalized: StoreOrder[] = rawList.map((o) => ({
        id: o.id ?? 0,
        orderNumber: o.orderNumber || o.code || (o.id ? `#${o.id}` : "—"),
        customerName: o.customerName || o.user?.name || o.customer?.name || "عميل فيورا",
        customerPhone: o.customerPhone || o.user?.phone || o.phone || null,
        customerEmail: o.customerEmail || o.user?.email || o.email || null,
        itemsCount: o.itemsCount ?? (Array.isArray(o.items) ? o.items.length : Array.isArray(o.orderItems) ? o.orderItems.length : 1),
        items: (o.items || o.orderItems || []).map((it) => ({
          id: it.id ?? 0,
          productName: it.productName || it.product?.name || "منتج",
          productImage: it.productImage || it.image || it.product?.imageUrl || it.product?.image || null,
          colorName: it.colorName || it.color || null,
          sizeName: it.sizeName || it.size || null,
          variant: it.variant || it.color || null,
          size: it.size || null,
          quantity: it.quantity ?? 1,
          unitPrice: String(it.unitPrice ?? it.price ?? 0),
          lineTotal: String(it.lineTotal ?? (Number(it.unitPrice ?? it.price ?? 0) * Number(it.quantity ?? 1))),
          price: String(it.unitPrice ?? it.price ?? 0),
        })),
        city: o.city || (typeof o.address === "object" ? o.address.city : undefined) || "—",
        address: (typeof o.address === "object" ? o.address.street : undefined) || (typeof o.address === "string" ? o.address : o.city || "—"),
        createdAt: o.createdAt || new Date().toISOString(),
        total: String(o.total ?? o.totalPrice ?? o.amount ?? 0),
        shippingFee: o.shippingFee ? String(o.shippingFee) : undefined,
        paymentMethod: o.paymentMethod || (o.paymentType === "COD" ? "CASH_ON_DELIVERY" : "ONLINE"),
        status: o.status || "NEW",
      }));

      setOrders(normalized);

      const rawCounts = res.statusCounts || res.counts;
      setCounts(rawCounts ? {...rawCounts, all: res.pagination?.total ?? normalized.length} : {all: res.pagination?.total ?? normalized.length});
      setPagination(res.pagination ?? null);
    } else {
      setError(res.message || t.admin.common.loadFailed);
    }
  }, [storeId, activeTab, queryText, sortOption, page]);

  useEffect(() => {
    // Initial fetch is synchronized with the selected store and filters.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void loadOrders();
    return () => { requestId.current++; };
  }, [loadOrders]);

  return (
    <div className="flex flex-col gap-6">
      {/* Header & Subtitle */}
      <div className="flex flex-col gap-1">
        <h2 className="text-xl font-extrabold text-heading">
          {t.admin.orders.title}
        </h2>
        <p className="text-sm text-text-secondary">
          {t.admin.orders.subtitle}
        </p>
      </div>

      <ErrorBanner message={error} onRetry={loadOrders} />

      {/* Tabs with Count Pills */}
      <div className="flex flex-wrap items-center gap-2 overflow-x-auto pb-1">
        {TABS.map((tab) => {
          const isActive = activeTab === tab.key;
          const count = counts[tab.key] ?? (tab.key === "all" ? counts.all : 0);

          return (
            <button
              key={tab.key}
              type="button"
              onClick={() => {
                setActiveTab(tab.key);
                setPage(1);
              }}
              className={`flex items-center gap-2 rounded-xl px-4 py-2 text-xs font-extrabold transition ${
                isActive
                  ? "bg-primary text-white shadow-xs"
                  : "border border-border/80 bg-surface text-text-secondary hover:border-primary/40 hover:text-heading"
              }`}
            >
              <span>{tab.label}</span>
              {typeof count === "number" && (
                <span
                  className={`rounded-full px-2 py-0.5 text-[11px] font-bold ${
                    isActive
                      ? "bg-white/20 text-white"
                      : "bg-field-bg text-text-secondary"
                  }`}
                >
                  {count}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* Search & Sort Toolbar */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative flex-1">
          <Search className="absolute right-3.5 top-1/2 size-4 -translate-y-1/2 text-text-secondary" />
          <input
            type="search"
            value={queryText}
            onChange={(e) => {
              setQueryText(e.target.value);
              setPage(1);
            }}
            placeholder={t.admin.orders.searchPlaceholder}
            className="h-10.5 w-full rounded-xl border border-border bg-surface pl-4 pr-10 text-sm text-heading placeholder:text-text-secondary/70 focus:border-primary focus:outline-hidden focus:ring-2 focus:ring-primary/20"
          />
        </div>

        <div className="flex items-center gap-2">
          <div className="relative">
            <select
              value={sortOption}
              onChange={(e) => {
                setSortOption(e.target.value as "newest" | "oldest" | "highest");
                setPage(1);
              }}
              className="h-10.5 appearance-none rounded-xl border border-border bg-surface pl-8 pr-4 text-xs font-bold text-heading hover:border-primary/40 focus:border-primary focus:outline-hidden"
            >
              <option value="newest">{t.admin.orders.sortNewest}</option>
              <option value="oldest">{t.admin.orders.sortOldest}</option>
              <option value="highest">{t.admin.orders.sortHighest}</option>
            </select>
            <ArrowUpDown className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-text-secondary" />
          </div>
        </div>
      </div>

      {/* Orders Table or Empty State */}
      {loading ? (
        <Card className="p-12">
          <Spinner />
        </Card>
      ) : orders.length === 0 ? (
        <Card className="border border-border p-8">
          <EmptyState
            icon={ShoppingBag}
            title={queryText || activeTab !== "all" ? t.admin.orders.noResults : t.admin.orders.empty}
            hint={t.admin.orders.emptyHint}
            action={
              queryText || activeTab !== "all" ? (
                <Button
                  variant="secondary"
                  size="sm"
                  onClick={() => {
                    setQueryText("");
                    setActiveTab("all");
                    setPage(1);
                  }}
                >
                  {t.admin.common.clearSearch}
                </Button>
              ) : undefined
            }
          />
        </Card>
      ) : (
        <div className="flex flex-col gap-4">
          <Card className="overflow-hidden border border-border shadow-xs">
            <TableShell minWidth="min-w-[950px]">
              <Thead columns={ORDER_COLUMNS} />
              <tbody className="divide-y divide-border/60">
                {orders.map((order) => (
                  <tr
                    key={order.id}
                    className="transition hover:bg-primary-soft/30"
                  >
                    <Td>
                      <span className="font-extrabold text-heading">
                        {order.orderNumber}
                      </span>
                    </Td>
                    <Td>
                      <div className="flex flex-col">
                        <span className="font-bold text-heading">
                          {order.customerName}
                        </span>
                        {order.customerPhone && (
                          <span className="ltr-nums text-xs text-text-secondary">
                            {order.customerPhone}
                          </span>
                        )}
                      </div>
                    </Td>
                    <Td className="ltr-nums font-medium text-text-secondary">
                      {order.itemsCount}
                    </Td>
                    <Td className="max-w-[200px] truncate text-text-secondary">
                      {order.address || order.city}
                    </Td>
                    <Td className="ltr-nums whitespace-nowrap text-text-secondary">
                      {formatDate(order.createdAt)}
                    </Td>
                    <Td>
                      <span className="ltr-nums font-bold text-heading">
                        {formatCurrency(Number(order.total))}
                      </span>
                    </Td>
                    <Td>
                      <Badge tone={order.paymentMethod === "ONLINE" ? "info" : "neutral"}>
                        {order.paymentMethod === "ONLINE"
                          ? t.admin.orders.paymentOnline
                          : t.admin.orders.paymentCOD}
                      </Badge>
                    </Td>
                    <Td>
                      <StatusBadge meta={STORE_ORDER_STATUS[order.status]} />
                    </Td>
                    <Td>
                      <Button
                        size="sm"
                        variant="secondary"
                        onClick={() => handleOpenOrder(order)}
                        icon={<Eye className="size-3.5" />}
                      >
                        {t.admin.orders.reviewOrder}
                      </Button>
                    </Td>
                  </tr>
                ))}
              </tbody>
            </TableShell>
          </Card>

          {pagination && pagination.totalPages > 1 && (
            <Pagination
              pagination={pagination}
              onChange={(newPage) => setPage(newPage)}
            />
          )}
        </div>
      )}

      {/* Order Detail Modal Dialog */}
      {selectedOrder && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div
            className="fixed inset-0 bg-black/40 backdrop-blur-xs transition-opacity"
            onClick={() => {
              setSelectedOrder(null);
              setOrderDetail(null);
            }}
          />

          <div className="relative z-10 max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-3xl border border-border bg-app-bg shadow-2xl">
            <div className="sticky top-0 z-10 flex items-start justify-between border-b border-border bg-surface px-6 py-5 sm:px-8">
              <div className="flex flex-col gap-1">
                <div className="flex items-center gap-2">
                  <h3 className="text-lg font-extrabold text-heading">
                    {t.admin.orders.detailsTitle}
                  </h3>
                </div>
                <p className="text-xs text-text-secondary">
                  {orderDetail?.orderNumber || selectedOrder.orderNumber} · {formatDate(orderDetail?.createdAt || selectedOrder.createdAt)}
                </p>
              </div>
              <button
                type="button"
                onClick={() => {
                  setSelectedOrder(null);
                  setOrderDetail(null);
                }}
                className="grid size-9 place-items-center rounded-xl text-text-secondary hover:bg-field-bg hover:text-heading cursor-pointer"
              >
                <XCircle className="size-5" />
              </button>
            </div>

            {loadingDetail ? (
              <div className="flex flex-col items-center justify-center py-12 text-center">
                <Spinner variant="inline" className="size-8 border-3" />
                <p className="mt-3 text-xs font-bold text-text-secondary">
                  جاري جلب تفاصيل الطلب الإدارية الكاملة...
                </p>
              </div>
            ) : (
              <div className="mt-6 flex flex-col gap-5 px-5 pb-5 sm:px-8 sm:pb-8">
                <section className="flex flex-col gap-4 rounded-2xl bg-primary p-5 text-icon sm:flex-row sm:items-center sm:justify-between">
                  <div>
                    <p className="text-xs font-bold text-icon/70">حالة الطلب</p>
                    <div className="mt-2">
                      <StatusBadge meta={STORE_ORDER_STATUS[orderDetail?.status || selectedOrder.status]} />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-5 text-start sm:text-end">
                    <div>
                      <p className="text-xs font-bold text-icon/70">إجمالي المنتجات</p>
                      <p className="mt-1 ltr-nums text-lg font-black">
                        {formatCurrency(Number(orderDetail?.money?.productsTotal ?? orderDetail?.subtotal ?? selectedOrder.total))}
                      </p>
                    </div>
                    <div>
                      <p className="text-xs font-bold text-icon/70">الإجمالي المطلوب</p>
                      <p className="mt-1 ltr-nums text-lg font-black">
                        {formatCurrency(Number(orderDetail?.total ?? selectedOrder.total))}
                      </p>
                    </div>
                  </div>
                </section>

                {/* 🌟 Multi-store Parent Group (Admin Perspective) */}
                {orderDetail?.group && (
                  <div className="rounded-xl border border-primary/20 bg-primary/5 p-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className="grid size-7 place-items-center rounded-lg bg-primary text-white">
                          <Layers className="size-4" />
                        </span>
                        <div>
                          <p className="text-xs font-black text-heading">
                            الطلبية الأم المشتركة (#{orderDetail.group.id})
                          </p>
                          <p className="text-[11px] font-bold text-text-secondary">
                            قام الزبون بطلب هذه السلة من {orderDetail.group.orders.length} متجر مختلف
                          </p>
                        </div>
                      </div>
                      <div className="text-left">
                        <span className="text-[10px] font-bold text-text-secondary block">
                          إجمالي ما دفعه الزبون بالكامل
                        </span>
                        <span className="ltr-nums text-sm font-black text-primary">
                          {formatCurrency(Number(orderDetail.group.totalAmount))}
                        </span>
                      </div>
                    </div>

                    {/* Sibling Stores in this Group */}
                    {orderDetail.group.orders.length > 1 && (
                      <div className="mt-3 divide-y divide-border/50 border-t border-border/60 pt-2">
                        <p className="mb-2 text-[11px] font-extrabold text-heading">
                          متاجر الطلبية الأخرى وحالتها:
                        </p>
                        <div className="space-y-1.5">
                          {orderDetail.group.orders.map((sib) => {
                            const isCurrent = sib.id === (orderDetail?.id || selectedOrder.id);
                            return (
                              <div
                                key={sib.id}
                                className={`flex items-center justify-between rounded-lg px-2.5 py-1.5 text-xs ${
                                  isCurrent
                                    ? "bg-surface font-black text-primary shadow-2xs"
                                    : "text-text-secondary"
                                }`}
                              >
                                <div className="flex items-center gap-2">
                                  <Store className="size-3.5 text-text-secondary" />
                                  <span>{sib.storeName || `متجر #${sib.storeId}`}</span>
                                  {isCurrent && (
                                    <span className="rounded bg-primary/10 px-1.5 py-0.2 text-[10px] font-extrabold text-primary">
                                      هذا الطلب
                                    </span>
                                  )}
                                </div>
                                <div className="flex items-center gap-3">
                                  <span className="ltr-nums font-bold">
                                    {formatCurrency(Number(sib.total))}
                                  </span>
                                  <StatusBadge meta={STORE_ORDER_STATUS[sib.status]} />
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </div>
                )}

                {/* Customer account and delivery information */}
                <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                  <div className="rounded-2xl border border-border bg-surface p-5 shadow-xs">
                    <p className="flex items-center gap-2 text-xs font-bold text-text-secondary">
                      <User className="size-4 text-primary" />
                      {t.admin.orders.customerInfo}
                    </p>
                    <p className="mt-2 text-sm font-bold text-heading">
                      {orderDetail?.customer?.name || selectedOrder.customerName}
                    </p>
                    {(orderDetail?.delivery?.recipientPhone || orderDetail?.customer?.phone || selectedOrder.customerPhone) && (
                      <p className="ltr-nums mt-1 text-xs text-text-secondary">
                        {orderDetail?.delivery?.recipientPhone || orderDetail?.customer?.phone || selectedOrder.customerPhone}
                      </p>
                    )}
                    {(orderDetail?.customer?.email || selectedOrder.customerEmail) && (
                      <p className="mt-1 text-xs text-text-secondary">
                        {orderDetail?.customer?.email || selectedOrder.customerEmail}
                      </p>
                    )}
                    {(orderDetail?.delivery?.recipientName || orderDetail?.recipientName) &&
                      (orderDetail?.delivery?.recipientName || orderDetail?.recipientName) !== (orderDetail?.customer?.name || selectedOrder.customerName) && (
                        <div className="mt-2 border-t border-border/50 pt-1.5 text-[11px] text-text-secondary">
                          <span className="font-bold">المستلم: </span>
                          <span>{orderDetail?.delivery?.recipientName || orderDetail?.recipientName}</span>
                          {(orderDetail?.delivery?.recipientPhone || orderDetail?.recipientPhone) && (
                            <span className="ltr-nums block">{orderDetail?.delivery?.recipientPhone || orderDetail?.recipientPhone}</span>
                          )}
                        </div>
                      )}
                  </div>

                  <div className="rounded-2xl border border-border bg-surface p-5 shadow-xs">
                    <p className="flex items-center gap-2 text-xs font-bold text-text-secondary">
                      <MapPin className="size-4 text-primary" />
                      {t.admin.orders.shippingAddress}
                    </p>
                    <p className="mt-2 text-sm font-bold text-heading">
                      {orderDetail?.delivery?.city || orderDetail?.city || selectedOrder.city}
                    </p>
                    <p className="mt-1 text-xs text-text-secondary">
                      {[orderDetail?.delivery?.area, orderDetail?.delivery?.street, orderDetail?.delivery?.details]
                        .filter(Boolean)
                        .join(" — ") || orderDetail?.address || selectedOrder.address}
                    </p>
                    {(orderDetail?.delivery?.notes || orderDetail?.notes) && (
                      <div className="mt-2 rounded bg-surface p-2 text-[11px] font-bold text-text-secondary">
                        <span className="text-primary font-black">ملاحظة التوصيل: </span>
                        {orderDetail?.delivery?.notes || orderDetail?.notes}
                      </div>
                    )}
                  </div>
                </div>

                {/* Items List */}
                <div className="overflow-hidden rounded-2xl border border-border bg-surface shadow-xs">
                  <h4 className="border-b border-border px-5 py-4 text-base font-extrabold text-heading">
                    {t.admin.orders.itemsList} ({(orderDetail?.items || selectedOrder.items || []).length})
                  </h4>
                  <div className="divide-y divide-border/70">
                    {(orderDetail?.items || selectedOrder.items || []).map((item) => {
                      const unitPrice = item.unitPrice ?? item.price;
                      const lineTotal = item.lineTotal ?? String(Number(unitPrice) * item.quantity);
                      const variant = [item.colorName ?? item.variant, item.sizeName ?? item.size]
                        .filter(Boolean)
                        .join(" · ");
                      const image = item.image ?? item.productImage;

                      return (
                      <article
                        key={item.id}
                        className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"
                      >
                        <div className="flex min-w-0 items-center gap-4">
                          {image ? (
                            <img
                              src={image}
                              alt={item.productName}
                              className="size-16 shrink-0 rounded-xl border border-border object-cover"
                            />
                          ) : (
                            <span className="grid size-16 shrink-0 place-items-center rounded-xl bg-field-bg text-text-secondary">
                              <Package className="size-5" />
                            </span>
                          )}
                          <div className="min-w-0">
                            <p className="truncate text-base font-extrabold text-heading">{item.productName}</p>
                            {variant && <p className="mt-1 text-sm text-text-secondary">{variant}</p>}
                          </div>
                        </div>
                        <div className="grid grid-cols-3 gap-3 rounded-xl bg-field-bg p-3 text-center sm:min-w-[290px]">
                          <div>
                            <p className="text-[11px] font-bold text-text-secondary">عدد القطع</p>
                            <p className="mt-1 ltr-nums font-black text-heading">{item.quantity}</p>
                          </div>
                          <div>
                            <p className="text-[11px] font-bold text-text-secondary">سعر القطعة</p>
                            <p className="mt-1 ltr-nums font-black text-heading">{formatCurrency(Number(unitPrice))}</p>
                          </div>
                          <div>
                            <p className="text-[11px] font-bold text-text-secondary">إجمالي المنتج</p>
                            <p className="mt-1 ltr-nums font-black text-primary">{formatCurrency(Number(lineTotal))}</p>
                          </div>
                        </div>
                      </article>
                    )})}
                  </div>
                </div>

                {/* Financial Summary */}
                <div className="rounded-2xl border border-border bg-field-bg/70 p-5">
                  <div className="flex items-center justify-between py-1 text-sm text-text-secondary">
                    <span>{t.admin.orders.subtotal}</span>
                    <span className="ltr-nums font-bold text-heading">
                      {formatCurrency(
                        Number(orderDetail?.money?.productsTotal ?? orderDetail?.subtotal ?? (Number(selectedOrder.total) - Number(selectedOrder.shippingFee || 0))),
                      )}
                    </span>
                  </div>
                  <div className="flex items-center justify-between py-1 text-sm text-text-secondary">
                    <span>{t.admin.orders.shippingFee}</span>
                    <span className="ltr-nums font-bold text-heading">
                      {Number(orderDetail?.money?.deliveryFee ?? orderDetail?.delivery?.fee ?? orderDetail?.shippingFee ?? selectedOrder.shippingFee) > 0
                        ? formatCurrency(Number(orderDetail?.money?.deliveryFee ?? orderDetail?.delivery?.fee ?? orderDetail?.shippingFee ?? selectedOrder.shippingFee))
                        : t.admin.orders.freeShipping}
                    </span>
                  </div>
                  <div className="flex items-center justify-between border-t border-border/80 pt-2 text-base font-extrabold text-heading">
                    <span>{t.admin.orders.grandTotal}</span>
                    <span className="ltr-nums text-primary font-black">
                      {formatCurrency(Number(orderDetail?.total ?? selectedOrder.total))}
                    </span>
                  </div>
                </div>
              </div>
            )}

            <div className="flex justify-end border-t border-border bg-surface px-5 py-4 sm:px-8">
              <Button
                onClick={() => {
                  setSelectedOrder(null);
                  setOrderDetail(null);
                }}
              >
                {t.admin.common.backToList}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
